"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[509],{9509:function(e,a,i){i.d(a,{I:function(){return r}});let r={en:{welcome:"Welcome to Raphael Sena's Portfolio! \uD83D\uDE04",theme:"Toggle Theme",profession:"Software Engineer",footer:"Made with \uD83E\uDD19 by @raphael-sena",fork:"Fork this project!",featured:"Featured Projects",projects:"Projects",viewRepo:"View Repository",about:"About",about_text:"Raphael Sena is a software developer who has evolved from hands-on IT support to building and modernizing real-world mobility and ERP systems. After early international experience studying in Sydney, he started his career in Service Desk/Help Desk roles, developing a strong foundation in troubleshooting, networks, hardware, and enterprise support. That customer-facing technical base later led to software engineering. Today, he works as a Fullstack Engineer at Modaxo (Empresa 1) on large-scale electronic ticketing and transit revenue platforms—shipping mobile apps used across multiple Brazilian cities and contributing to modernization efforts with Flutter and Java/Spring. Alongside professional work, he builds personal projects, combining product mindset with fullstack execution across mobile, backend, frontend, and cloud/devops. He is also a Software Engineering student at PUC Minas (2023–2027), continuously strengthening his engineering fundamentals while applying them in production environments and side projects with Java, Angular, PostgreSQL and Docker.",experience:"Experience",currently:"Currently",cuido_bem:"In this role, I contribute by leading the back-end development team and participating in various projects as needed. My contributions to the 'Cuido Bem' project so far include: - Reviewing colleagues' code and suggesting improvements; - Writing unit tests for the MVC structure; - Implementing a GlobalExceptionHandler to effectively manage back-end exceptions.",cuido_bem_projects:"Projects",skills:"Skills",technician:"IT Technician",technician_text:"I configured and verified networks on desktops and laptops. Verified and installed hardware. Performed maintenance on computers and laptops. Provided L1 technical support using Active Directory, ticketing systems (CSC), VPN, directory and printer mapping platforms, following established SLA standards. Collaborated on a telephony change project serving over 100 users, migrating logical telephony networks to VOIP and configuring/installing devices.",technician_assistant:"Information Technology Assistant",technician_assistant_text:"Service Desk Assistant",intern:"Information Technology Intern",intern_text:"Service Desk intern.",avaso:"Provide English-language support for a multicultural user base. Diagnosed, researched, and resolved issues across desktops, laptops, VMs, smartphones, servers, backup systems, VoIP devices, and peripherals. Installed and configured devices and updated documents in a ticketing system for tracking and reporting.",avaso_title:"Field Support Engineer",avaso_freelance:"Service Desk (Freelance)",servicedesk_helpdesk:"ServiceDesk and HelpDesk",education:"Education",highschool:"Year 11 - High School",kogarah:"High School exchange in Sydney, Australia.",bh:"\uD83D\uDCCD Belo Horizonte/MG - Brazil",sydney:"\uD83D\uDCCD Sydney/NSW - Australia",engineering:"Bachelor Software Engineering",engineering_text:"I am currently studying Software Engineering at PUC Minas, where I acquire knowledge in system development, requirements analysis, and software architecture. During my degree, I have specialized in back-end and agile development technologies.",interdisciplinary_project:"Interdisciplinary Project Champion",interdisciplinary_project_text:"Led an award-winning team in high-impact, real-world software project.",experimental_agency:"Experimental Software Agency - PMMG",experimental_agency_text:"As a Tech Lead, I am leading a team to build the human-resources selection process software scope for Minas Gerais State Military Police, impacting more than 40000 candidates per public tender.",extracurricular:"Extracurricular",alura_java_url:"https://drive.google.com/file/d/1dxsLorrXwDCNB_u1-X7IrlB74zbVwC8M/view?usp=sharing",alura_java_poo_png:"/2026/extracurricular/alura/alura_java_poo_en.png",alura_javascript_url:"https://drive.google.com/file/d/1CClEytR90nr3xdyrK3P2FkjaeePeCyEI/view?usp=sharing",alura_javascript_png:"/2026/extracurricular/alura/alura_javascript_en.png",udemy_java_url:"https://drive.google.com/file/d/1bEq4DXe6MPFIYGv728N0PRkvfyA5CQiI/view?usp=sharing",udemy_java_png:"/2026/extracurricular/udemy/java_udemy_en.jpg",redhat_sysadmin_url:"https://drive.google.com/file/d/13e21aJ5wTt2Vu235F29Jl2chxPXo8mbi/view?usp=sharing",redhat_sysadmin_jpg:"/2026/extracurricular/redhat/Certificate-of-Attendance-_RH124-9.0_.jpg",whatsapp_message:"Hi, how are you? My name is [Your Name], and I am [your occupation/field of expertise]. I’m reaching out because I believe we can create a partnership to develop impactful solutions together. If you’re interested, I’d be delighted to discuss further and align ideas. \uD83D\uDE04",technologies:"Technologies",programmingLanguages:"Programming Languages",observability:"Observability",messaging:"Messaging & Caching",resume:"Resume",resumeUrl:"/2026/Resume_Raphael_Sena.pdf",chess:"Chess",chess_text:"I love playing chess, a game that stimulates concentration, logical thinking, and strategic decision-making. Besides being fun, it helps me develop skills like problem-solving.",profile:"Profile",name:"Name",followers:"Followers",stats:"Statistics",rapid:"Rapid",last_score:"Last Score",best_score:"High Score",total_wins:"Total Wins",total_losses:"Total Losses",spotify_text:"I enjoy music as a whole; I'm quite eclectic. I adore Brazilian music and listen a lot to bossa nova, samba, and MPB. Besides national music, I like to listen to a bit of neo-psychedelia, indie, indie rock, jazz, and so on... I really love music!",december:"Dec",may:"May",tools:"Development Tools",e1:{software_engineer:"Software Engineer",project_sigom_cloud:"Project Sigom Cloud",project_sigom_cloud_text:"Sigom Cloud is an ERP/Transit Revenue Management, available in SaaS style. Worked as a Fullstack developer operating with Java 1.8, Spring Boot, and AngularJS. Optimized PIX payment report generation by redesigning the algorithm and reducing execution paths by 42.6%; for 1M records, reduced estimated work from 20M–1T to 1M operations.",project_sigo:"Project SIGO",project_sigo_text:"SIGO is a mobile app for electronic ticketing for public transport across small and large metropolitan cities around Brazil, such as Guarulhos, SP; Florian\xf3polis, SC; Uberl\xe2ndia, MG and many others. Worked as a Fullstack developer dealing with the technologies C# with Xamarin for the mobile app and Java 1.7 and Spring Boot 1.5. The app is available on Apple App Store and Android Google Play and it reached out over 177K people.",project_sigo_2:"Project SIGO 2.0",project_sigo_2_text:"SIGO 2.0 is a modernization of SIGO. Worked as a Fullstack developer using the technologies Dart with Flutter kit for the mobile app and Java 1.7 and Spring Boot 1.5. Worked on the following functionalities: Card Statement, FAQ, Alerts, User Registering, Profile Editing, Orders and My Cards sections and Moovit integrations with GTFS and GTFS-RT for route planning and real time lines tracking."}},pt:{welcome:"Bem-vindo(a) ao Portf\xf3lio de Raphael Sena! \uD83D\uDE04",theme:"Alterar Tema",profession:"Engenheiro de Software",footer:"Feito com \uD83E\uDD19 por @raphael-sena",fork:"D\xea um fork neste projeto!",featured:"Projetos em Destaque",projects:"Projetos",viewRepo:"Ver Reposit\xf3rio",about:"Sobre",about_text:"Raphael Sena \xe9 um desenvolvedor de software que evoluiu do suporte de TI na pr\xe1tica para a constru\xe7\xe3o e moderniza\xe7\xe3o de sistemas reais de mobilidade e ERP. Ap\xf3s uma experi\xeancia internacional inicial estudando em Sydney, iniciou sua carreira em fun\xe7\xf5es de Service Desk/Help Desk, desenvolvendo uma base em troubleshooting, redes, hardware e suporte corporativo. Essa viv\xeancia t\xe9cnica voltada ao cliente posteriormente o levou \xe0 engenharia de software. Hoje, atua como Engenheiro Fullstack na Modaxo (Empresa 1) em plataformas de bilhetagem eletr\xf4nica e gest\xe3o de receita do transporte em larga escala — entregando aplicativos m\xf3veis utilizados em diversas cidades brasileiras e contribuindo para esfor\xe7os de moderniza\xe7\xe3o com Flutter e Java/Spring. Paralelamente ao trabalho profissional, desenvolve projetos pessoais, combinando mentalidade de produto com execu\xe7\xe3o fullstack em mobile, backend, frontend e cloud/devops. Tamb\xe9m \xe9 estudante de Engenharia de Software na PUC Minas (2023–2027), fortalecendo continuamente seus fundamentos de engenharia enquanto aplica esse conhecimento em ambientes de produ\xe7\xe3o e projetos paralelos com Java, Angular, PostgreSQL e Docker.",experience:"Experi\xeancia",currently:"Atualmente",cuido_bem:"Neste papel, contribuo liderando a equipe de desenvolvimento back-end e participando de v\xe1rios projetos conforme necess\xe1rio. Minhas contribui\xe7\xf5es para o projeto 'Cuido Bem' at\xe9 agora incluem: - Revisar o c\xf3digo dos colegas e sugerir melhorias; - Escrever testes unit\xe1rios para a estrutura MVC; - Implementar um GlobalExceptionHandler para gerenciar eficazmente as exce\xe7\xf5es de back-end.",cuido_bem_projects:"Projetos",skills:"Compet\xeancias",technician:"T\xe9cnico de TI",technician_text:"Configurei e verifiquei redes em desktops e notebooks. Verifiquei e instalei hardware. Realizei manuten\xe7\xe3o em computadores e notebooks. Prestei suporte t\xe9cnico N1 utilizando Active Directory, sistema de chamados (CSC), VPN, plataformas de mapeamento de diret\xf3rios e impressoras, seguindo padr\xf5es de SLA estabelecidos. Colaborei em um projeto de mudan\xe7a de telefonia para mais de 100 usu\xe1rios, migrando redes l\xf3gicas de telefonia para VoIP e configurando/instalando equipamentos.",technician_assistant:"Assistente T\xe9cnico de TI",technician_assistant_text:"Assistente de Service Desk",intern:"Information Technology Intern",intern_text:"Estagi\xe1rio de Service Desk.",avaso:"Presto suporte em ingl\xeas para uma base de usu\xe1rios multicultural. Diagnostiquei, pesquisei e resolvi problemas em desktops, notebooks, VMs, smartphones, servidores, sistemas de backup, dispositivos VoIP e perif\xe9ricos. Realizei instala\xe7\xe3o e configura\xe7\xe3o de equipamentos e atualizei documenta\xe7\xf5es em sistema de chamados para rastreio e relat\xf3rios.",avaso_title:"Field Support Engineer",avaso_freelance:"Service Desk (Freelance)",servicedesk_helpdesk:"ServiceDesk e HelpDesk",education:"Educa\xe7\xe3o",highschool:"2\xba Ano - Ensino M\xe9dio",kogarah:"Interc\xe2mbio do ensino m\xe9dio em Sydney, Austr\xe1lia.",bh:"\uD83D\uDCCD Belo Horizonte/MG - Brasil",sydney:"\uD83D\uDCCD Sydney/NGS - Austr\xe1lia",engineering:"Bacharelado de Engenharia de Software",engineering_text:"Estou cursando Engenharia de Software na PUC Minas, onde adquiro conhecimentos em desenvolvimento de sistemas, an\xe1lise de requisitos e arquitetura de software. Durante a gradua\xe7\xe3o, tenho me especializado em back-end e tecnologias de desenvolvimento \xe1gil.",interdisciplinary_project:"Campe\xe3o de Projeto Interdisciplinar",interdisciplinary_project_text:"Liderei uma equipe premiada em um projeto de software de alto impacto e aplica\xe7\xe3o no mundo real.",experimental_agency:"Ag\xeancia Experimental de Software - PMMG",experimental_agency_text:"Como Tech Lead, lidero uma equipe para construir o escopo do software de processo seletivo de recursos humanos da Pol\xedcia Militar de Minas Gerais, impactando mais de 40.000 candidatos por concurso p\xfablico.",extracurricular:"Extracurricular",alura_java_url:"https://drive.google.com/file/d/1my2dosjLglVMcyOGIlx-ZGS9_FuIb7rV/view?usp=sharing",alura_java_poo_png:"/2026/extracurricular/alura/alura_java_poo_pt.png",alura_javascript_url:"https://drive.google.com/file/d/1CClEytR90nr3xdyrK3P2FkjaeePeCyEI/view?usp=sharing",alura_javascript_png:"/2026/extracurricular/alura/alura_javascript_pt.png",udemy_java_url:"https://drive.google.com/file/d/13xjOGajuXWw6j6GkfqPmN-6VmLmCvU1k/view?usp=sharing",udemy_java_png:"/2026/extracurricular/udemy/java_udemy_pt.jpg",redhat_sysadmin_url:"https://drive.google.com/file/d/13e21aJ5wTt2Vu235F29Jl2chxPXo8mbi/view?usp=sharing",redhat_sysadmin_jpg:"/2026/extracurricular/redhat/Certificate-of-Attendance-_RH124-9.0_.jpg",whatsapp_message:"Ol\xe1, tudo bem? Meu nome \xe9 [Seu Nome] e sou [sua ocupa\xe7\xe3o/\xe1rea de atua\xe7\xe3o]. Estou entrando em contato porque acredito que podemos criar uma parceria para desenvolver solu\xe7\xf5es de impacto juntos. Caso tenha interesse, ficarei muito feliz em conversar mais e alinhar ideias. \uD83D\uDE04",technologies:"Tecnologias",programmingLanguages:"Linguagens de Programa\xe7\xe3o",observability:"Observabilidade",messaging:"Mensageria & Cache",resume:"Curr\xedculo",resumeUrl:"/Curr\xedculo_Raphael_Sena.pdf",chess:"Xadrez",chess_text:"Eu adoro jogar xadrez, um jogo que estimula a concentra\xe7\xe3o, o racioc\xednio l\xf3gico e a tomada de decis\xf5es estrat\xe9gicas. Al\xe9m de divertido, ele me ajuda a desenvolver habilidades como resolu\xe7\xe3o de problemas.",profile:"Perfil",name:"Nome",followers:"Seguidores",stats:"Estat\xedsticas",rapid:"R\xe1pida",last_score:"\xdaltima pontua\xe7\xe3o",best_score:"Melhor pontua\xe7\xe3o",total_wins:"Vit\xf3rias",total_losses:"Derrotas",spotify_text:"Gosto muito de m\xfasica em um todo, sou bastante ecl\xe9tico. Adoro a m\xfasica brasileira e escuto muito bossa nova, samba e MPB. Al\xe9m da m\xfasica nacional, gosto de escutar um pouco de neo-psicodelia, indie, indie rock, jazz, enfim... Gosto muito de m\xfasica!",december:"Dez",may:"Mai",tools:"Ferramentas de Desevolvimento",e1:{software_engineer:"Engenheiro de Software",project_sigom_cloud:"Projeto Sigom Cloud",project_sigom_cloud_text:"Sigom Cloud \xe9 um ERP/Sistema de Gest\xe3o de Receita do Transporte, oferecido no modelo SaaS. Atuei como desenvolvedor Fullstack com Java 1.8, Spring Boot e AngularJS. Otimizei a gera\xe7\xe3o de relat\xf3rios de pagamento via PIX ao redesenhar o algoritmo e reduzir os caminhos de execu\xe7\xe3o em 42,6%; para 1M de registros, reduzi o esfor\xe7o estimado de 20M–1T para 1M opera\xe7\xf5es.",project_sigo:"Projeto SIGO",project_sigo_text:"SIGO \xe9 um aplicativo m\xf3vel de bilhetagem eletr\xf4nica para transporte p\xfablico em cidades pequenas e grandes regi\xf5es metropolitanas do Brasil, como Guarulhos, SP; Florian\xf3polis, SC; Uberl\xe2ndia, MG e muitas outras. Atuei como desenvolvedor Fullstack utilizando C# com Xamarin no app mobile e Java 1.7 com Spring Boot 1.5. O app est\xe1 dispon\xedvel na Apple App Store e na Google Play e alcan\xe7ou mais de 177 mil pessoas.",project_sigo_2:"Projeto SIGO 2.0",project_sigo_2_text:"O SIGO 2.0 \xe9 uma moderniza\xe7\xe3o do SIGO. Atuei como desenvolvedor Fullstack utilizando as tecnologias Dart com o kit Flutter para o aplicativo mobile e Java 1.7 e Spring Boot 1.5. Trabalhei nas seguintes funcionalidades: Extrato do Cart\xe3o, FAQ, Alertas, Cadastro de Usu\xe1rio, Edi\xe7\xe3o de Perfil, se\xe7\xf5es de Pedidos e Meus Cart\xf5es, al\xe9m de integra\xe7\xf5es com o Moovit via GTFS e GTFS-RT para planejamento de rotas e acompanhamento de linhas em tempo real."}},de:{welcome:"Willkommen in Raphael Senas Portfolio! \uD83D\uDE04",theme:"Thema Umschalten",profession:"Softwaretechniker",footer:"Mit \uD83E\uDD19 gemacht von @raphael-sena",fork:"Forken Sie dieses Projekt!",featured:"Ausgew\xe4hlte Projekte",projects:"Projekte",viewRepo:"Repository anzeigen",about:"\xdcber",about_text:"Raphael Sena ist ein Softwareentwickler, der sich vom praktischen IT-Support zur Entwicklung und Modernisierung realer Mobilit\xe4ts- und ERP-Systeme entwickelt hat. Nach fr\xfchen internationalen Erfahrungen beim Studium in Sydney begann er seine Karriere in Service-Desk/Help-Desk-Rollen und entwickelte eine solide Grundlage in Troubleshooting, Netzwerken, Hardware und Unternehmensunterst\xfctzung. Diese kundenorientierte technische Basis f\xfchrte sp\xe4ter zur Softwareentwicklung. Heute arbeitet er als Fullstack-Ingenieur bei Modaxo (Empresa 1) an gro\xdfangelegten elektronischen Ticketing- und Transiteinnahmenplattformen – er liefert mobile Apps, die in mehreren brasilianischen St\xe4dten eingesetzt werden, und tr\xe4gt zu Modernisierungsbem\xfchungen mit Flutter und Java/Spring bei. Neben der beruflichen Arbeit entwickelt er pers\xf6nliche Projekte und kombiniert dabei Produktdenken mit Fullstack-Umsetzung \xfcber Mobile, Backend, Frontend und Cloud/DevOps. Er ist au\xdferdem Student der Softwaretechnik an der PUC Minas (2023–2027) und st\xe4rkt kontinuierlich seine technischen Grundlagen, w\xe4hrend er sie in Produktionsumgebungen und Nebenprojekten mit Java, Angular, PostgreSQL und Docker anwendet.",experience:"Erfahrung",currently:"Zurzeit",cuido_bem:"In dieser Rolle trage ich dazu bei, das Back-End-Entwicklungsteam zu leiten und an verschiedenen Projekten nach Bedarf teilzunehmen. Meine bisherigen Beitr\xe4ge zum Projekt 'Cuido Bem' umfassen: - Den Code meiner Kollegen zu \xfcberpr\xfcfen und Verbesserungsvorschl\xe4ge zu machen; - Unit-Tests f\xfcr die MVC-Struktur zu schreiben; - Einen GlobalExceptionHandler zu implementieren, um Back-End-Ausnahmen effektiv zu verwalten.",cuido_bem_projects:"Projekte",skills:"Kompetenzen",technician:"IT-Techniker",technician_text:"Konfiguration und \xdcberpr\xfcfung von Netzwerken auf Desktops und Laptops. Hardware \xfcberpr\xfcft und installiert. Wartung an Computern und Laptops durchgef\xfchrt. L1-technischen Support mit Active Directory, Ticketsystemen (CSC), VPN, Verzeichnis- und Druckerzuordnungsplattformen bereitgestellt, gem\xe4\xdf festgelegten SLA-Standards. An einem Telefoniewechselprojekt f\xfcr \xfcber 100 Benutzer mitgearbeitet, logische Telefonienetzwerke zu VoIP migriert und Ger\xe4te konfiguriert/installiert.",technician_assistant:"IT-Assistent",technician_assistant_text:"Assistent am Service Desk",intern:"IT-Praktikant",intern_text:"Praktikant am Service Desk.",avaso:"Englischsprachiger Support f\xfcr eine multikulturelle Benutzerbasis. Diagnose, Recherche und L\xf6sung von Problemen bei Desktops, Laptops, VMs, Smartphones, Servern, Backup-Systemen, VoIP-Ger\xe4ten und Peripherieger\xe4ten. Installation und Konfiguration von Ger\xe4ten und Aktualisierung von Dokumenten in einem Ticketsystem f\xfcr Tracking und Reporting.",avaso_title:"Field Support Engineer",avaso_freelance:"Service Desk (Freelance)",servicedesk_helpdesk:"ServiceDesk und HelpDesk",education:"Bildung",highschool:"Klasse 11 - Gymnasium",kogarah:"Highschool-Austausch in Sydney, Australien.",bh:"\uD83D\uDCCD Belo Horizonte/MG - Brasilien",sydney:"\uD83D\uDCCD Sydney/NSW - Australien",engineering:"Bachelor Softwaretechnik",engineering_text:"Ich studiere Softwaretechnik an der PUC Minas, wo ich Kenntnisse in Systementwicklung, Anforderungsanalyse und Softwarearchitektur erwerbe. W\xe4hrend meines Studiums habe ich mich auf Back-End und agile Entwicklungstechnologien spezialisiert.",interdisciplinary_project:"Champion f\xfcr interdisziplin\xe4re Projekte",interdisciplinary_project_text:"Leitete ein preisgekr\xf6ntes Team in einem wirkungsvollen, praxisnahen Softwareprojekt.",experimental_agency:"Experimentelle Software-Agentur - PMMG",experimental_agency_text:"Als Tech Lead leite ich ein Team, um den Umfang der Software f\xfcr den Personalauswahlprozess der Milit\xe4rpolizei von Minas Gerais zu erstellen, was mehr als 40.000 Kandidaten pro \xf6ffentlicher Ausschreibung betrifft.",extracurricular:"Extracurricular",alura_java_url:"https://drive.google.com/file/d/1dxsLorrXwDCNB_u1-X7IrlB74zbVwC8M/view?usp=sharing",alura_java_poo_png:"/2026/extracurricular/alura/alura_java_poo_en.png",alura_javascript_url:"https://drive.google.com/file/d/1CClEytR90nr3xdyrK3P2FkjaeePeCyEI/view?usp=sharing",alura_javascript_png:"/2026/extracurricular/alura/alura_javascript_en.png",udemy_java_url:"https://drive.google.com/file/d/1bEq4DXe6MPFIYGv728N0PRkvfyA5CQiI/view?usp=sharing",udemy_java_png:"/2026/extracurricular/udemy/java_udemy_en.jpg",redhat_sysadmin_url:"https://drive.google.com/file/d/13e21aJ5wTt2Vu235F29Jl2chxPXo8mbi/view?usp=sharing",redhat_sysadmin_jpg:"/2026/extracurricular/redhat/Certificate-of-Attendance-_RH124-9.0_.jpg",whatsapp_message:"Hallo, wie geht es Ihnen? Mein Name ist [Ihr Name], und ich bin [Ihr Beruf/Fachgebiet]. Ich melde mich, weil ich glaube, dass wir eine Partnerschaft eingehen k\xf6nnen, um gemeinsam wirkungsvolle L\xf6sungen zu entwickeln. Wenn Sie Interesse haben, w\xfcrde ich mich freuen, mehr dar\xfcber zu sprechen und Ideen auszutauschen. \uD83D\uDE04",technologies:"Technologieen",programmingLanguages:"Programmiersprachen",observability:"Beobachtbarkeit",messaging:"Messaging & Caching",resume:"Lebenslauf",resumeUrl:"/2026/Resume_Raphael_Sena.pdf",chess:"Schach",chess_text:"Ich liebe es, Schach zu spielen, ein Spiel, das die Konzentration, das logische Denken und strategische Entscheidungen f\xf6rdert. Neben dem Spa\xdf hilft es mir, F\xe4higkeiten wie Probleml\xf6sung zu entwickeln.",profile:"Profil",name:"Name",followers:"Follower",stats:"Statistiken",rapid:"Schnell",last_score:"Letzter Punktestand",best_score:"Bestes Ergebnis",total_wins:"Gesamtgewinne",total_losses:"Gesamtverluste",spotify_text:"Ich mag Musik insgesamt sehr; ich bin ziemlich vielseitig. Ich liebe brasilianische Musik und h\xf6re viel Bossa Nova, Samba und MPB. Neben nationaler Musik h\xf6re ich auch gerne ein bisschen Neo-Psychedelia, Indie, Indie-Rock, Jazz und so weiter... Ich liebe Musik wirklich sehr!",december:"Dez",may:"Mai",tools:"Entwicklungswerkzeuge",e1:{software_engineer:"Software-Ingenieur",project_sigom_cloud:"Projekt Sigom Cloud",project_sigom_cloud_text:"Sigom Cloud ist ein ERP/Transit-Umsatzverwaltungssystem, das im SaaS-Stil verf\xfcgbar ist. Arbeitete als Fullstack-Entwickler mit Java 1.8, Spring Boot und AngularJS. Optimierte die PIX-Zahlungsberichterstattung durch Neugestaltung des Algorithmus und Reduzierung der Ausf\xfchrungspfade um 42,6%; f\xfcr 1M Datens\xe4tze wurde der gesch\xe4tzte Aufwand von 20M–1T auf 1M Operationen reduziert.",project_sigo:"Projekt SIGO",project_sigo_text:"SIGO ist eine mobile App f\xfcr elektronische Ticketierung im \xf6ffentlichen Nahverkehr in kleinen und gro\xdfen Metropolregionen Brasiliens, wie Guarulhos, SP; Florian\xf3polis, SC; Uberl\xe2ndia, MG und vielen anderen. Arbeitete als Fullstack-Entwickler mit C# und Xamarin f\xfcr die mobile App sowie Java 1.7 und Spring Boot 1.5. Die App ist im Apple App Store und bei Google Play verf\xfcgbar und erreichte \xfcber 177.000 Menschen.",project_sigo_2:"Projekt SIGO 2.0",project_sigo_2_text:"SIGO 2.0 ist eine Modernisierung von SIGO. Arbeitete als Fullstack-Entwickler mit Dart und dem Flutter-Kit f\xfcr die mobile App sowie Java 1.7 und Spring Boot 1.5. Arbeitete an folgenden Funktionen: Kartenabrechnung, FAQ, Benachrichtigungen, Benutzerregistrierung, Profilbearbeitung, Bestellungen und Meine Karten-Bereiche sowie Moovit-Integrationen mit GTFS und GTFS-RT f\xfcr Routenplanung und Echtzeitverfolgung von Linien."}}}}}]);